net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.ThumbnailParameter(
    new java.awt.Dimension(100, 100),
    null,
    true,
    net.coobird.thumbnailator.ThumbnailParameter.ORIGINAL_FORMAT,
    net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_FORMAT_TYPE,
    net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_QUALITY,
    net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_IMAGE_TYPE,
    java.util.Collections.emptyList(),
    net.coobird.thumbnailator.resizers.DefaultResizerFactory.getInstance(),
    true,
    false
);

boolean keepAspectRatio = param.isKeepAspectRatio();

assert keepAspectRatio == true : "keepAspectRatio should match the value provided in the constructor";
System.out.println("__CHECK__ isKeepAspectRatio " + keepAspectRatio);
